"""Decorators instrumenting ASR engine connect and disconnect."""

from rasa.tracing.voice.metrics import VoiceComponent
from rasa.tracing.voice.recorders.asr.span_attributes import (
    connect_attributes,
    engine_attributes,
)
from rasa.tracing.voice.recorders.connection import (
    observed_connect,
    observed_disconnect,
)
from rasa.tracing.voice.shared import semconv

# Apply to ASREngine.connect and to every provider override of connect().
traced_asr_connect = observed_connect(
    semconv.SPAN_NAME_CONNECT_ASR,
    connect_attributes,
    VoiceComponent.ASR,
)

# Apply to ASREngine.close_connection and to every provider override of it.
traced_asr_disconnect = observed_disconnect(
    semconv.SPAN_NAME_DISCONNECT_ASR,
    engine_attributes,
    VoiceComponent.ASR,
)
